   133→// --- HELPER FUNCTIONS ---
   134→export function extractRecordId(url: unknown): string | null {
   135→  if (!url) return null;
   136→  if (typeof url !== 'string') return null;
   137→  const match = url.match(/([a-f0-9]{24})$/i);
   138→  return match ? match[1] : null;
   139→}
   140→
   141→export function createRecordUrl(appId: string, recordId: string): string {
   142→  return `https://ci04.ci.xist4c.de/rest/apps/${appId}/records/${recordId}`;
   143→}
   144→
   145→async function callApi(method: string, endpoint: string, data?: any) {
   146→  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
   147→    method,
   148→    headers: { 'Content-Type': 'application/json' },
   149→    credentials: 'include',  // Nutze Session Cookies für Auth
   150→    body: data ? JSON.stringify(data) : undefined
   151→  });
   152→  if (!response.ok) throw new Error(await response.text());
   153→  // DELETE returns often empty body or simple status
   154→  if (method === 'DELETE') return true;
   155→  return response.json();
   156→}
