   158→/** Upload a file to LivingApps. Returns the file URL for use in record fields. */
   159→export async function uploadFile(file: File | Blob, filename?: string): Promise<string> {
   160→  const formData = new FormData();
   161→  formData.append('file', file, filename ?? (file instanceof File ? file.name : 'upload'));
   162→  const res = await fetch(`${API_BASE_URL}/files`, {
   163→    method: 'POST',
   164→    credentials: 'include',
   165→    body: formData,
   166→  });
   167→  if (!res.ok) throw new Error(`File upload failed: ${res.status}`);
   168→  const data = await res.json();
   169→  return data.url;
   170→}
