   580→
   581→/** Extract display label from lookup/select or lookup/radio API response */
   582→export function displayLookup(val: unknown, options?: {key: string, label: string}[]): string {
   583→  if (val == null) return '—';
   584→  if (typeof val === 'object' && val !== null && 'label' in val) return String((val as Record<string, unknown>).label);
   585→  if (options && typeof val === 'string') { const m = options.find(o => o.key === val); if (m) return m.label; }
   586→  return String(val);
   587→}
   588→
   589→/** Extract labels from multiplelookup/checkbox API response */
   590→export function displayMultiLookup(val: unknown, options?: {key: string, label: string}[]): string {
   591→  if (val == null) return '—';
   592→  if (Array.isArray(val)) return val.map(v => {
   593→    if (typeof v === 'object' && v !== null && 'label' in v) return String((v as Record<string, unknown>).label);
   594→    if (options && typeof v === 'string') { const m = options.find(o => o.key === v); if (m) return m.label; }
   595→    return String(v);
   596→  }).join(', ') || '—';
   597→  return displayLookup(val, options);
   598→}
   599→
   600→/** Extract key from lookup value (handles both {key,label} objects and plain strings) */
   601→export function lookupKey(val: unknown): string | undefined {
   602→  if (val == null) return undefined;
   603→  if (typeof val === 'object' && val !== null && 'key' in val) return String((val as Record<string, unknown>).key);
   604→  if (typeof val === 'string') return val;
   605→  return undefined;
   606→}
   607→
   608→/** Extract keys from multiplelookup value */
   609→export function lookupKeys(val: unknown): string[] {
   610→  if (!Array.isArray(val)) return [];
   611→  return val.map(v => typeof v === 'object' && v !== null && 'key' in v ? String((v as Record<string, unknown>).key) : String(v));
   612→}
