   617→const AI_ENDPOINT = "https://ci04.ci.xist4c.de/litellm/v1/chat/completions";
   618→const AI_MODEL = "default";
   619→
   620→export type ChatMessage = {
   621→  role: "system" | "user" | "assistant";
   622→  content: string | Array<{ type: string; [key: string]: unknown }>;
   623→};
   624→
   625→type CompletionOptions = {
   626→  temperature?: number;
   627→  max_tokens?: number;
   628→  top_p?: number;
   629→  stop?: string[];
   630→  response_format?: { type: string };
   631→};
   632→
   633→export async function chatCompletion(
   634→  messages: ChatMessage[],
   635→  options: CompletionOptions = {}
   636→): Promise<string> {
   637→  const res = await fetch(AI_ENDPOINT, {
   638→    method: "POST",
   639→    headers: { "Content-Type": "application/json", Accept: "application/json" },
   640→    body: JSON.stringify({ model: AI_MODEL, messages, ...options }),
   641→  });
   642→  if (!res.ok) {
   643→    const body = await res.text();
   644→    throw new Error(`AI API ${res.status}: ${body}`);
   645→  }
   646→  const data = await res.json();
   647→  return data.choices[0].message.content;
   648→}
   649→
   650→export async function safeJsonCompletion<T = unknown>(
   651→  messages: ChatMessage[],
   652→  options: CompletionOptions = {}
   653→): Promise<T> {
   654→  const raw = await chatCompletion(messages, options);
   655→  const match = raw.match(/\{[\s\S]*\}|\[[\s\S]*\]/);
   656→  if (!match) throw new Error(`Expected JSON but got: ${raw.slice(0, 200)}`);
   657→  return JSON.parse(match[0]);
   658→}
   659→
   660→export async function withRetry<T>(fn: () => Promise<T>, maxAttempts = 3): Promise<T> {
   661→  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
   662→    try {
   663→      return await fn();
   664→    } catch (err) {
   665→      if (attempt === maxAttempts) throw err;
   666→      await new Promise((r) => setTimeout(r, 1000 * attempt));
   667→    }
   668→  }
   669→  throw new Error("unreachable");
   670→}
   671→
   672→// --- File encoding helpers ---
   673→
   674→export function fileToDataUri(file: File): Promise<string> {
   675→  return new Promise((resolve, reject) => {
   676→    const reader = new FileReader();
   677→    reader.onload = () => resolve(reader.result as string);
   678→    reader.onerror = () => reject(new Error("Failed to read file"));
   679→    reader.readAsDataURL(file);
   680→  });
   681→}
   682→
   683→export async function urlToDataUri(url: string): Promise<string> {
   684→  const res = await fetch(url);
   685→  const blob = await res.blob();
   686→  return new Promise((resolve, reject) => {
   687→    const reader = new FileReader();
   688→    reader.onload = () => resolve(reader.result as string);
   689→    reader.onerror = () => reject(new Error("Failed to encode file"));
   690→    reader.readAsDataURL(blob);
   691→  });
   692→}
   693→
   694→/** Convert a data URI back to a Blob (for file uploads) */
   695→export function dataUriToBlob(dataUri: string): Blob {
   696→  const [header, base64] = dataUri.split(',');
   697→  const mime = header.match(/:(.*?);/)?.[1] ?? 'application/octet-stream';
   698→  const bytes = atob(base64);
   699→  const arr = new Uint8Array(bytes.length);
   700→  for (let i = 0; i < bytes.length; i++) arr[i] = bytes.charCodeAt(i);
   701→  return new Blob([arr], { type: mime });
   702→}
