                `flex items-center px-4 py-2 rounded-2xl text-sm transition-colors ${
                  isActive
                    ? 'bg-sidebar-accent text-sidebar-accent-foreground font-medium'
                    : 'text-sidebar-foreground font-normal hover:bg-sidebar-accent/50 hover:text-sidebar-accent-foreground'
                }`
              }
            >
              {item.name}
            </NavLink>
          ))}
        </nav>

        <div className="mt-auto px-3 pb-4">
          <div className="border-t border-sidebar-border pt-3">
            <NavLink
              to='/admin'
              onClick={() => setSidebarOpen(false)}
              className={({ isActive }: { isActive: boolean }) =>
                `flex items-center gap-2 px-4 py-2 rounded-2xl text-sm transition-colors ${
                  isActive
                    ? 'bg-sidebar-accent text-sidebar-accent-foreground font-medium'
                    : 'text-sidebar-foreground/60 font-normal hover:bg-sidebar-accent/50 hover:text-sidebar-accent-foreground'
                }`
              }
            >
              <Settings size={16} />
              Verwaltung
            </NavLink>
          </div>
        </div>
        </div>
      </aside>

      <div className="lg:pl-64">
        <header className="lg:hidden flex items-center gap-4 px-4 py-3 border-b bg-card sticky top-0 z-30">
          <button
            className="p-2 rounded-lg hover:bg-accent transition-colors"
            onClick={() => setSidebarOpen(true)}
          >
            <Menu size={18} />
          </button>
          <span className="font-semibold text-sm">{APP_TITLE}</span>
        </header>
        <main className="p-6 lg:p-8 max-w-screen-2xl">
          <Outlet />
        </main>
      </div>

      <ChatWidget />
    </div>
  );
}

